WITH metrics AS (SELECT id, city, region, opened_date, sqft, AVG(sqft) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_sqft, MIN(sqft) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_sqft, SUM(sqft) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_sqft, ROW_NUMBER() OVER (PARTITION BY region ORDER BY opened_date, id) AS event_seq FROM stores WHERE region = 'South') SELECT id, city, opened_date, sqft, running_min_sqft, event_seq FROM metrics ORDER BY opened_date DESC NULLS FIRST;
